INSERT INTO recipes (title, description, ingredients, instructions, cooking_time, servings, calories, protein, carbs, fats, category, tags, is_active)
VALUES
('Овсяная каша с ягодами', 'Полезный и питательный завтрак с овсянкой и свежими ягодами', '["100г овсяных хлопьев", "200мл молока", "50г черники", "50г малины", "1 ст.л. меда"]', 'Залейте овсянку молоком и варите 5-7 минут. Добавьте ягоды и мед. Перемешайте и подавайте теплым.', 10, 1, 320, 12, 54, 6, 'завтрак', '["здоровое питание", "быстрый завтрак"]', true),
('Греческий салат', 'Классический средиземноморский салат с овощами и сыром фета', '["100г помидоров", "1 огурец", "100г феты", "50г маслин", "1 луковица", "Оливковое масло"]', 'Нарежьте овощи крупными кусками. Добавьте фету и маслины. Заправьте оливковым маслом.', 15, 2, 280, 14, 18, 18, 'обед', '["салат", "вегетарианское"]', true),
('Куриная грудка с овощами', 'Запеченная куриная грудка с овощами в духовке', '["200г куриной грудки", "150г брокколи", "100г моркови", "Специи", "Оливковое масло"]', 'Замаринуйте курицу со специями. Запекайте с овощами при 180°C 25 минут.', 30, 1, 380, 35, 25, 12, 'обед', '["белковое", "запеченное"]', true),
('Лосось с киноа', 'Запеченный лосось с киноа и овощами', '["200г филе лосося", "100г киноа", "150г спаржи", "Лимон", "Специи"]', 'Отварите киноа. Запекайте лосось 15 минут при 180°C. Приготовьте спаржу на пару.', 25, 1, 520, 42, 40, 22, 'ужин', '["рыба", "полезные жиры"]', true),
('Тыквенный суп-пюре', 'Нежный крем-суп из тыквы с имбирем', '["400г тыквы", "1 луковица", "2 зубчика чеснока", "Имбирь", "Кокосовое молоко"]', 'Обжарьте лук и чеснок. Добавьте тыкву и имбирь. Варите 20 минут. Взбейте блендером.', 30, 4, 180, 5, 28, 8, 'обед', '["суп", "вегетарианское"]', true),
('Омлет с овощами', 'Воздушный омлет с болгарским перцем и помидорами', '["3 яйца", "1 болгарский перец", "2 помидора", "Зелень", "Сыр"]', 'Взбейте яйца. Обжарьте овощи. Залейте яйцами и готовьте под крышкой 5 минут.', 12, 1, 280, 18, 12, 16, 'завтрак', '["яйца", "быстрый завтрак"]', true),
('Говядина терияки с рисом', 'Нежная говядина в соусе терияки с бурым рисом', '["200г говядины", "100г бурого риса", "Соус терияки", "Кунжут", "Зеленый лук"]', 'Отварите рис. Обжарьте говядину с соусом терияки. Подавайте с кунжутом и луком.', 35, 1, 480, 38, 52, 14, 'ужин', '["мясо", "азиатская кухня"]', true),
('Смузи-боул с гранолой', 'Питательный смузи-боул с ягодами и гранолой', '["200г замороженных ягод", "1 банан", "100мл йогурта", "50г гранолы", "Семена чиа"]', 'Взбейте ягоды, банан и йогурт в блендере. Украсьте гранолой и семенами.', 8, 1, 340, 12, 58, 8, 'завтрак', '["смузи", "суперфуды"]', true),
('Запеченная индейка с бататом', 'Сочная индейка с запеченным бататом и розмарином', '["200г филе индейки", "150г батата", "Розмарин", "Чеснок", "Оливковое масло"]', 'Замаринуйте индейку со специями. Запекайте с бататом при 190°C 30 минут.', 35, 1, 480, 45, 38, 12, 'ужин', '["мясо птицы", "запеченное"]', true),
('Творожная запеканка', 'Нежная творожная запеканка с изюмом', '["400г творога", "2 яйца", "50г манки", "50г изюма", "Ванилин", "Мед"]', 'Смешайте все ингредиенты. Выпекайте при 180°C 40 минут до золотистой корочки.', 50, 4, 220, 16, 24, 8, 'завтрак', '["творожное", "выпечка"]', true)
